using System;using System.Data;using System.Data.SQLite;using System.IO;using System.Windows.Forms;
namespace WindowsFormsApp1.Data
{
    public class OperacoesRepository
    {
        private readonly string cs;
        public OperacoesRepository(){string p=Path.Combine(Application.StartupPath,"Data");Directory.CreateDirectory(p);cs="Data Source="+Path.Combine(p,"hotel.db")+";Version=3;";using(var c=Abrir())using(var q=c.CreateCommand()){q.CommandText=@"CREATE TABLE IF NOT EXISTS Clientes(Id INTEGER PRIMARY KEY AUTOINCREMENT,Nome TEXT NOT NULL,Cpf TEXT NOT NULL UNIQUE,Rg TEXT,DataNascimento TEXT,Sexo TEXT,Rua TEXT,Cep TEXT,Bairro TEXT,Cidade TEXT,Estado TEXT,Pais TEXT,Celular TEXT,Telefone1 TEXT,Telefone2 TEXT);CREATE TABLE IF NOT EXISTS Quartos(Id INTEGER PRIMARY KEY AUTOINCREMENT,Numero TEXT NOT NULL UNIQUE,Categoria TEXT NOT NULL,Capacidade INTEGER NOT NULL,ValorDiaria NUMERIC NOT NULL);CREATE TABLE IF NOT EXISTS Reservas(Id INTEGER PRIMARY KEY AUTOINCREMENT,ClienteId INTEGER NOT NULL,QuartoId INTEGER NOT NULL,Entrada TEXT NOT NULL,Saida TEXT NOT NULL,Adultos INTEGER,Criancas INTEGER,ValorTotal NUMERIC,Observacao TEXT,Status TEXT NOT NULL DEFAULT 'Reservada');CREATE TABLE IF NOT EXISTS SacChamados(Id INTEGER PRIMARY KEY AUTOINCREMENT,Cliente TEXT NOT NULL,Assunto TEXT NOT NULL,Descricao TEXT,Status TEXT NOT NULL,DataAbertura TEXT NOT NULL);CREATE TABLE IF NOT EXISTS Consumos(Id INTEGER PRIMARY KEY AUTOINCREMENT,ReservaId INTEGER NOT NULL,ProdutoId INTEGER NOT NULL,Quantidade INTEGER NOT NULL,ValorUnitario NUMERIC NOT NULL,Data TEXT NOT NULL);";q.ExecuteNonQuery();}}
        private SQLiteConnection Abrir(){var c=new SQLiteConnection(cs);c.Open();return c;}
        public DataTable Financeiro(){DataTable t=new DataTable();using(var c=Abrir())using(var q=new SQLiteCommand(@"SELECT r.Id Reserva,c.Nome Cliente,q.Numero Quarto,r.ValorTotal Hospedagem,COALESCE(SUM(co.Quantidade*co.ValorUnitario),0) Consumo,r.ValorTotal+COALESCE(SUM(co.Quantidade*co.ValorUnitario),0) Total,r.Status FROM Reservas r JOIN Clientes c ON c.Id=r.ClienteId JOIN Quartos q ON q.Id=r.QuartoId LEFT JOIN Consumos co ON co.ReservaId=r.Id GROUP BY r.Id,c.Nome,q.Numero,r.ValorTotal,r.Status ORDER BY r.Id DESC",c))using(var a=new SQLiteDataAdapter(q))a.Fill(t);return t;}
        public decimal Receita(){using(var c=Abrir())using(var q=new SQLiteCommand(@"SELECT COALESCE((SELECT SUM(ValorTotal) FROM Reservas WHERE Status<>'Cancelada'),0)+COALESCE((SELECT SUM(Quantidade*ValorUnitario) FROM Consumos),0)",c))return Convert.ToDecimal(q.ExecuteScalar());}
        public DataTable ListarSac(){DataTable t=new DataTable();using(var c=Abrir())using(var a=new SQLiteDataAdapter("SELECT Id,Cliente,Assunto,Descricao,Status,DataAbertura FROM SacChamados ORDER BY Id DESC",c))a.Fill(t);return t;}
        public void AbrirChamado(string cliente,string assunto,string descricao){using(var c=Abrir())using(var q=new SQLiteCommand("INSERT INTO SacChamados(Cliente,Assunto,Descricao,Status,DataAbertura) VALUES(@c,@a,@d,'Aberto',@data)",c)){q.Parameters.AddWithValue("@c",cliente);q.Parameters.AddWithValue("@a",assunto);q.Parameters.AddWithValue("@d",descricao);q.Parameters.AddWithValue("@data",DateTime.Now.ToString("s"));q.ExecuteNonQuery();}}
        public void FecharChamado(long id){using(var c=Abrir())using(var q=new SQLiteCommand("UPDATE SacChamados SET Status='Resolvido' WHERE Id=@id",c)){q.Parameters.AddWithValue("@id",id);q.ExecuteNonQuery();}}
    }
}
